def transform(grid):
    # The pattern is made of alternating 0/background stripes; recolor the
    # background cells between consecutive 0 cells in each row to 2.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = next((v for v in counts if v != background and v != 2), None)
    if foreground is None:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v == foreground]
        for a, b in zip(cols, cols[1:]):
            if b == a + 2 and row[a + 1] == background:
                out[r][a + 1] = 2
    return out

